            400, "chain_id must match [A-Za-z0-9_-]{1,128}"
        )

@staticmethod
def _validate_hex_32(value: object, name: str) -> None:
    if not _is_lower_hex_32(value):
        raise ServiceError(
            400, f"{name} must be 64 lowercase hex characters"
        )

@staticmethod
