                f"wallet {wallet_id!r} has non-alternating asset freeze "
                f"events for asset {asset_id!r}"
            )
        expected_by_asset[asset_id] = (
            audit.TYPE_ASSET_UNFROZEN
            if expected == audit.TYPE_ASSET_FROZEN
